with expected(name)as(values('ac_dce_work_items'),('ac_dce_edit_presence'),('ac_dce_field_edits'),('ac_dce_text_documents'),('ac_dce_editorial_authors'),('ac_dce_activity_v2'),('ac_dce_processing_outputs'),('ac_dce_disposal_items'),('ac_dce_production_sources'),('ac_dce_service_cursor'))select name,to_regclass('public.'||name)is not null as exists,coalesce((select relrowsecurity from pg_class where oid=to_regclass('public.'||name)),false)as rls_enabled,(select obj_description(to_regclass('public.'||name),'pg_class'))='ANGELCARE_DCE_PROFESSIONAL_R4'as owner_marker,case when to_regclass('public.'||name)is null then false else not has_table_privilege('anon',to_regclass('public.'||name),'SELECT')and not has_table_privilege('authenticated',to_regclass('public.'||name),'SELECT')end as browser_roles_denied from expected order by name;
with expected(name)as(values('ac_dce_approval_exception'),('ac_dce_author_evidence'),('ac_dce_case_operation'),('ac_dce_disposal_execute'),('ac_dce_disposal_finish'),('ac_dce_disposal_prepare'),('ac_dce_editorial_guard'),('ac_dce_editorial_notice'),('ac_dce_field_patch'),('ac_dce_json_set'),('ac_dce_patch_references'),('ac_dce_processing_action'),('ac_dce_professional_health'),('ac_dce_rebind'),('ac_dce_response_stamp'),('ac_dce_retention_hold'),('ac_dce_service_batch'),('ac_dce_service_scopes'),('ac_dce_strategy'),('ac_dce_text_commit'),('ac_dce_work_page'),('ac_dce_work_write'))select e.name,p.oid is not null as exists,obj_description(p.oid,'pg_proc')='ANGELCARE_DCE_PROFESSIONAL_R4'as owner_marker,case when p.oid is null then false else not has_function_privilege('anon',p.oid,'EXECUTE')and not has_function_privilege('authenticated',p.oid,'EXECUTE')and has_function_privilege('service_role',p.oid,'EXECUTE')end as service_only from expected e left join pg_proc p on p.pronamespace='public'::regnamespace and p.proname=e.name order by e.name;
select tgname,not tgisinternal as application_trigger,tgenabled<>'D' as enabled from pg_trigger where tgname in('ac_dce_editorial_guard_trigger','ac_dce_author_evidence_trigger','ac_dce_patch_references_trigger','ac_dce_editorial_notice_trigger')order by tgname;
select 'ANGELCARE_DCE_PROFESSIONAL_R4_SQL_VERIFIED' as result;
